```python
# tests/test_zip_dicts.py

import pytest

from your_module import zip_dicts  # replace with the actual module name


def test_zip_dicts_happy_path_with_overlapping_and_missing_keys():
    d1 = {"a": 1, "b": 2}
    d2 = {"b": 20, "c": 30}
    d3 = {"a": 10, "c": 300}

    result = zip_dicts(d1, d2, d3)

    assert result == {
        "a": [1, None, 10],
        "b": [2, 20, None],
        "c": [None, 30, 300],
    }


def test_values_are_ordered_by_input_dictionary_order():
    result = zip_dicts(
        {"x": "first"},
        {"x": "second"},
        {"x": "third"},
    )

    assert result == {"x": ["first", "second", "third"]}


def test_single_dict_wraps_values_in_single_item_lists():
    result = zip_dicts({"a": 1, "b": 2})

    assert result == {
        "a": [1],
        "b": [2],
    }


@pytest.mark.parametrize(
    ("args", "expected"),
    [
        ((), {}),
        (({},), {}),
        (({}, {}), {}),
        (({}, {"a": 1}, {}), {"a": [None, 1, None]}),
    ],
)
def test_empty_input_cases(args, expected):
    assert zip_dicts(*args) == expected


def test_none_values_and_missing_keys_both_result_in_none():
    result = zip_dicts(
        {"a": None, "b": "present"},
        {"b": None, "c": 3},
    )

    assert result == {
        "a": [None, None],
        "b": ["present", None],
        "c": [None, 3],
    }


def test_supports_non_string_hashable_keys():
    tuple_key = ("tuple", 1)

    result = zip_dicts(
        {1: "one", tuple_key: "tuple value"},
        {tuple_key: "updated tuple value"},
    )

    assert result == {
        1: ["one", None],
        tuple_key: ["tuple value", "updated tuple value"],
    }


def test_input_dicts_are_not_mutated():
    d1 = {"a": 1}
    d2 = {"b": 2}

    original_d1 = d1.copy()
    original_d2 = d2.copy()

    assert zip_dicts(d1, d2) == {
        "a": [1, None],
        "b": [None, 2],
    }

    assert d1 == original_d1
    assert d2 == original_d2


@pytest.mark.parametrize(
    ("args", "expected_exception"),
    [
        ((None,), TypeError),
        ((123,), TypeError),
        (({"a": 1}, None), TypeError),
        ((["a"],), AttributeError),
        (({"a": 1}, ["a"]), AttributeError),
        (([["unhashable"]],), TypeError),
    ],
)
def test_invalid_inputs_raise_expected_exceptions(args, expected_exception):
    with pytest.raises(expected_exception):
        zip_dicts(*args)
```

Note: the error tests reflect the current implementation’s behavior. If you later add explicit type validation, you may want all invalid inputs to consistently raise `TypeError` instead.
